const NOVA_PURCHASING_ASSETS={"/purchases":{"body":"<!doctype html>\n<html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>المشتريات | NOVA Rx</title><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link href=\"https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800&display=swap\" rel=\"stylesheet\"><link rel=\"stylesheet\" href=\"/purchases.css\"></head>\n<body><div class=\"app\"><aside class=\"nav\"><a class=\"brand\" href=\"/\">NOVA <b>Rx</b></a><p>صيدلية السوسي</p><a href=\"/#sale\">البيع</a><a href=\"/purchases\" aria-current=\"page\">المشتريات</a><button id=\"openSettings\">إعدادات الموردين</button><a href=\"https://elsousypharmacy-create.github.io/pharmacy/orders.html\" target=\"_blank\" rel=\"noopener\">نواقص الداشبورد ↗</a><div class=\"nav-note\">تجهيز الطلبيات<br>الإدخال على فارما كليك</div></aside>\n<main><header><div><h1>المشتريات</h1><p>النواقص وعروض الموردين في مكان واحد</p></div><div class=\"source\"><span id=\"sourceState\">STOCK LIVE · اضغط تحديث النواقص</span><small id=\"sourceTime\"></small></div></header>\n<section class=\"controls\" aria-label=\"إعداد الطلب\"><label>مدة التغطية بالأيام<input id=\"days\" inputmode=\"numeric\" type=\"text\" value=\"21\" aria-describedby=\"coverageHint\"></label><fieldset><legend>مستوى المخزون</legend><div class=\"segment\"><button id=\"minimum\" aria-pressed=\"false\">الحد الأدنى</button><button id=\"ideal\" aria-pressed=\"true\">المثالي</button></div></fieldset><button id=\"load\" class=\"secondary\">تحديث النواقص</button><button id=\"distribute\" class=\"primary\">توزيع تلقائي<small>أعلى خصم</small></button></section>\n<p id=\"coverageHint\" class=\"hint\">الكمية تغطي المدة المطلوبة ولا تقل عن المستوى المختار. لو معدل البيع غير متاح نستخدم المستوى المسجل ونوضح ذلك.</p>\n<p id=\"status\" role=\"status\" aria-live=\"polite\">اختَر إعدادات الموردين، ثم حدّث النواقص.</p>\n<div class=\"workspace\"><section class=\"products panel\"><div class=\"panel-head\"><h2>الأصناف المطلوبة <small id=\"count\"></small></h2><input id=\"search\" type=\"search\" placeholder=\"ابحث عن صنف…\" aria-label=\"بحث في النواقص\"></div><div class=\"table-wrap\"><table><thead><tr><th><input id=\"selectAll\" type=\"checkbox\" aria-label=\"تحديد الأصناف الظاهرة\"></th><th>الصنف</th><th>الرصيد</th><th>المستهدف</th><th>المطلوب</th><th>العرض والخصم</th><th>تعديل</th></tr></thead><tbody id=\"rows\"><tr><td colspan=\"7\" class=\"empty\">ستظهر هنا النواقص من بيانات الصيدلية بعد الاتصال.</td></tr></tbody></table></div><footer id=\"tableHint\">اختيار المخازن يحدد العروض المسموح بها في التوزيع.</footer></section>\n<aside class=\"cart panel\"><div class=\"panel-head\"><h2>توزيع الطلب</h2><span id=\"groupCount\"></span></div><div id=\"groups\"><p class=\"empty\">جهّز قائمة النواقص ثم وزّع الأصناف على الموردين.</p></div><div class=\"cart-footer\"><strong id=\"total\">— ج.م</strong><button id=\"review\" class=\"primary\" disabled>مراجعة قائمة التجهيز</button><small>قائمة نوفا المحلية؛ الإضافة لسلة المورد لا تتم إلا بتأكيد منفصل وقراءة النتيجة.</small></div></aside></div></main></div>\n<dialog id=\"settings\"><form method=\"dialog\"><div class=\"dialog-head\"><h2>إعدادات الموردين</h2><button class=\"close\" value=\"cancel\" aria-label=\"إغلاق الإعدادات\">×</button></div></form><div class=\"dialog-body\"><p>اختيارات الموردين والمخازن محفوظة على الجهاز. بيانات الدخول للموردين محفوظة على السيرفر.</p><label class=\"check\"><input id=\"supplier-aumet\" type=\"checkbox\"> أوميت <span id=\"aumetState\"></span></label><label class=\"check\"><input id=\"supplier-pharmaoverseas\" type=\"checkbox\"> فارما أوفرسيز <span id=\"pharmaState\"></span></label><h3>مخازن أوميت المسموح بها</h3><button id=\"refreshSellers\" class=\"secondary\">تحديث قائمة المخازن</button><input id=\"sellerSearch\" type=\"search\" placeholder=\"ابحث عن مخزن…\" aria-label=\"بحث عن مخزن\"><div id=\"sellers\"><p>اضغط تحديث لقراءة مخازن حسابك.</p></div><label class=\"credential\">رقم دخول الداشبورد لقراءة النواقص<input id=\"dashboardPin\" type=\"password\" autocomplete=\"off\" placeholder=\"يُستخدم خلال فتح الصفحة فقط\"></label><small>رقم الداشبورد لا يُحفظ على الجهاز. قد يُطلب رقم موردين نوفا عند الاتصال.</small></div><div class=\"dialog-actions\"><button id=\"saveSettings\" class=\"primary\">حفظ الاختيارات</button></div></dialog>\n<dialog id=\"offers\"><div class=\"dialog-head\"><h2 id=\"offerTitle\">اختيار عرض</h2><button id=\"closeOffers\" class=\"close\" aria-label=\"إغلاق العروض\">×</button></div><div id=\"offerRows\" class=\"dialog-body\"></div></dialog>\n<dialog id=\"reviewDialog\"><div class=\"dialog-head\"><h2>مراجعة قائمة التجهيز</h2><button id=\"closeReview\" class=\"close\" aria-label=\"إغلاق المراجعة\">×</button></div><div class=\"dialog-body\"><p class=\"notice\">لم تُرسل هذه القائمة إلى أي مورد. لا يوجد طلب شراء منفذ.</p><div id=\"reviewGroups\"></div><p id=\"savedState\" role=\"status\"></p><p id=\"cartStatus\" role=\"status\"></p><div id=\"cartPlans\"></div></div><div class=\"dialog-actions\"><button id=\"saveDraft\" class=\"primary\">حفظ قائمة نوفا</button><button id=\"prepareAumet\" class=\"secondary\">قراءة سلة أوميت وتجهيز الإضافة</button><button id=\"applyAumet\" class=\"primary\" hidden>تأكيد الإضافة لسلة أوميت</button><button id=\"copyDraft\" class=\"secondary\">نسخ القائمة</button></div></dialog>\n<script src=\"/supplier-provider.js\"></script><script type=\"module\" src=\"/purchases.js\"></script></body></html>\n","type":"text/html"},"/purchases.html":{"body":"<!doctype html>\n<html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>المشتريات | NOVA Rx</title><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link href=\"https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800&display=swap\" rel=\"stylesheet\"><link rel=\"stylesheet\" href=\"/purchases.css\"></head>\n<body><div class=\"app\"><aside class=\"nav\"><a class=\"brand\" href=\"/\">NOVA <b>Rx</b></a><p>صيدلية السوسي</p><a href=\"/#sale\">البيع</a><a href=\"/purchases\" aria-current=\"page\">المشتريات</a><button id=\"openSettings\">إعدادات الموردين</button><a href=\"https://elsousypharmacy-create.github.io/pharmacy/orders.html\" target=\"_blank\" rel=\"noopener\">نواقص الداشبورد ↗</a><div class=\"nav-note\">تجهيز الطلبيات<br>الإدخال على فارما كليك</div></aside>\n<main><header><div><h1>المشتريات</h1><p>النواقص وعروض الموردين في مكان واحد</p></div><div class=\"source\"><span id=\"sourceState\">STOCK LIVE · اضغط تحديث النواقص</span><small id=\"sourceTime\"></small></div></header>\n<section class=\"controls\" aria-label=\"إعداد الطلب\"><label>مدة التغطية بالأيام<input id=\"days\" inputmode=\"numeric\" type=\"text\" value=\"21\" aria-describedby=\"coverageHint\"></label><fieldset><legend>مستوى المخزون</legend><div class=\"segment\"><button id=\"minimum\" aria-pressed=\"false\">الحد الأدنى</button><button id=\"ideal\" aria-pressed=\"true\">المثالي</button></div></fieldset><button id=\"load\" class=\"secondary\">تحديث النواقص</button><button id=\"distribute\" class=\"primary\">توزيع تلقائي<small>أعلى خصم</small></button></section>\n<p id=\"coverageHint\" class=\"hint\">الكمية تغطي المدة المطلوبة ولا تقل عن المستوى المختار. لو معدل البيع غير متاح نستخدم المستوى المسجل ونوضح ذلك.</p>\n<p id=\"status\" role=\"status\" aria-live=\"polite\">اختَر إعدادات الموردين، ثم حدّث النواقص.</p>\n<div class=\"workspace\"><section class=\"products panel\"><div class=\"panel-head\"><h2>الأصناف المطلوبة <small id=\"count\"></small></h2><input id=\"search\" type=\"search\" placeholder=\"ابحث عن صنف…\" aria-label=\"بحث في النواقص\"></div><div class=\"table-wrap\"><table><thead><tr><th><input id=\"selectAll\" type=\"checkbox\" aria-label=\"تحديد الأصناف الظاهرة\"></th><th>الصنف</th><th>الرصيد</th><th>المستهدف</th><th>المطلوب</th><th>العرض والخصم</th><th>تعديل</th></tr></thead><tbody id=\"rows\"><tr><td colspan=\"7\" class=\"empty\">ستظهر هنا النواقص من بيانات الصيدلية بعد الاتصال.</td></tr></tbody></table></div><footer id=\"tableHint\">اختيار المخازن يحدد العروض المسموح بها في التوزيع.</footer></section>\n<aside class=\"cart panel\"><div class=\"panel-head\"><h2>توزيع الطلب</h2><span id=\"groupCount\"></span></div><div id=\"groups\"><p class=\"empty\">جهّز قائمة النواقص ثم وزّع الأصناف على الموردين.</p></div><div class=\"cart-footer\"><strong id=\"total\">— ج.م</strong><button id=\"review\" class=\"primary\" disabled>مراجعة قائمة التجهيز</button><small>قائمة نوفا المحلية؛ الإضافة لسلة المورد لا تتم إلا بتأكيد منفصل وقراءة النتيجة.</small></div></aside></div></main></div>\n<dialog id=\"settings\"><form method=\"dialog\"><div class=\"dialog-head\"><h2>إعدادات الموردين</h2><button class=\"close\" value=\"cancel\" aria-label=\"إغلاق الإعدادات\">×</button></div></form><div class=\"dialog-body\"><p>اختيارات الموردين والمخازن محفوظة على الجهاز. بيانات الدخول للموردين محفوظة على السيرفر.</p><label class=\"check\"><input id=\"supplier-aumet\" type=\"checkbox\"> أوميت <span id=\"aumetState\"></span></label><label class=\"check\"><input id=\"supplier-pharmaoverseas\" type=\"checkbox\"> فارما أوفرسيز <span id=\"pharmaState\"></span></label><h3>مخازن أوميت المسموح بها</h3><button id=\"refreshSellers\" class=\"secondary\">تحديث قائمة المخازن</button><input id=\"sellerSearch\" type=\"search\" placeholder=\"ابحث عن مخزن…\" aria-label=\"بحث عن مخزن\"><div id=\"sellers\"><p>اضغط تحديث لقراءة مخازن حسابك.</p></div><label class=\"credential\">رقم دخول الداشبورد لقراءة النواقص<input id=\"dashboardPin\" type=\"password\" autocomplete=\"off\" placeholder=\"يُستخدم خلال فتح الصفحة فقط\"></label><small>رقم الداشبورد لا يُحفظ على الجهاز. قد يُطلب رقم موردين نوفا عند الاتصال.</small></div><div class=\"dialog-actions\"><button id=\"saveSettings\" class=\"primary\">حفظ الاختيارات</button></div></dialog>\n<dialog id=\"offers\"><div class=\"dialog-head\"><h2 id=\"offerTitle\">اختيار عرض</h2><button id=\"closeOffers\" class=\"close\" aria-label=\"إغلاق العروض\">×</button></div><div id=\"offerRows\" class=\"dialog-body\"></div></dialog>\n<dialog id=\"reviewDialog\"><div class=\"dialog-head\"><h2>مراجعة قائمة التجهيز</h2><button id=\"closeReview\" class=\"close\" aria-label=\"إغلاق المراجعة\">×</button></div><div class=\"dialog-body\"><p class=\"notice\">لم تُرسل هذه القائمة إلى أي مورد. لا يوجد طلب شراء منفذ.</p><div id=\"reviewGroups\"></div><p id=\"savedState\" role=\"status\"></p><p id=\"cartStatus\" role=\"status\"></p><div id=\"cartPlans\"></div></div><div class=\"dialog-actions\"><button id=\"saveDraft\" class=\"primary\">حفظ قائمة نوفا</button><button id=\"prepareAumet\" class=\"secondary\">قراءة سلة أوميت وتجهيز الإضافة</button><button id=\"applyAumet\" class=\"primary\" hidden>تأكيد الإضافة لسلة أوميت</button><button id=\"copyDraft\" class=\"secondary\">نسخ القائمة</button></div></dialog>\n<script src=\"/supplier-provider.js\"></script><script type=\"module\" src=\"/purchases.js\"></script></body></html>\n","type":"text/html"},"/purchases.css":{"body":":root{color-scheme:dark;--bg:#0d1116;--panel:#181e25;--field:#11171e;--line:#303b47;--text:#eef2f6;--muted:#9eabb9;--blue:#397dac;--light:#90c4e7}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.65 Cairo,Tahoma,sans-serif}button,input,select{font:inherit;color:inherit}button,a,input{touch-action:manipulation}button{cursor:pointer}button:disabled{opacity:.45;cursor:default}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid var(--light);outline-offset:3px}button{border:1px solid var(--line);border-radius:9px;background:#202832;min-height:44px;padding:9px 16px}input:not([type=checkbox]),select{min-height:44px;border:1px solid var(--line);background:var(--field);border-radius:8px;padding:8px 12px;min-width:0}input[type=checkbox]{width:22px;height:22px;accent-color:var(--blue);cursor:pointer}input.qty{width:76px;text-align:center;direction:ltr}.primary{background:var(--blue);border-color:#5796c2;font-weight:700}.secondary{background:#242d37}small,.hint{color:var(--muted);font-size:11px}button small{display:block;color:inherit;font-weight:400}.app{display:grid;grid-template-columns:178px minmax(0,1fr);height:100dvh;overflow:hidden}.nav{border-left:1px solid var(--line);padding:24px 14px;display:flex;flex-direction:column;gap:12px;background:#10161d}.brand{font-size:27px;font-weight:800;direction:ltr;align-self:center;text-decoration:none;color:var(--text)}.brand b{color:var(--light)}.nav p{text-align:center;color:var(--muted);margin:0 0 25px}.nav>a:not(.brand),.nav>button{display:block;text-decoration:none;color:inherit;text-align:right;padding:12px;border:1px solid transparent;border-radius:9px}.nav a[aria-current]{background:#2c668e!important;border-color:#4c85ab!important}.nav-note{margin-top:auto;color:var(--muted);font-size:11px;text-align:center}main{padding:22px 24px;min-width:0;display:flex;flex-direction:column;overflow:hidden}header{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:18px}h1,h2,h3,p{margin:0}h1{font-size:28px}h2{font-size:18px}header p{color:var(--muted)}.source{display:flex;flex-direction:column;text-align:left;font-size:12px;color:var(--muted)}.source.ready{color:#8ec5a9}.controls{display:flex;align-items:end;gap:16px;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:16px;flex-wrap:wrap}.controls label{display:flex;flex-direction:column;gap:7px;font-weight:700}.controls #days{width:135px;text-align:center;font-size:19px;direction:ltr}.controls fieldset{border:0;padding:0;margin:0}.controls legend{padding:0 0 7px}.segment{display:flex}.segment button{border-radius:0;padding:10px 20px}.segment button:first-child{border-radius:0 8px 8px 0}.segment button:last-child{border-radius:8px 0 0 8px}.segment button[aria-pressed=true]{background:#2f6b95;border-color:#5293c0}.controls #load{margin-right:auto}#status{font-size:12px;min-height:30px;padding:3px 0 10px;color:var(--light)}.hint{margin-top:7px}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 275px;gap:14px;min-height:0;flex:1}.panel{border:1px solid var(--line);border-radius:12px;background:var(--panel);min-width:0;overflow:hidden;display:flex;flex-direction:column}.panel-head{padding:15px;display:flex;gap:12px;align-items:center;justify-content:space-between}.panel-head input{width:170px}.table-wrap{overflow:auto;flex:1}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px}th,td{text-align:right;padding:10px 8px;border-bottom:1px solid var(--line);vertical-align:middle;overflow-wrap:anywhere}th{background:#252e39;color:#b5c0cc;position:sticky;top:0;z-index:1;font-size:11px}th:first-child{width:38px}th:nth-child(2){width:27%}th:nth-child(3),th:nth-child(4){width:65px}th:nth-child(5){width:90px}th:last-child{width:65px}td small{display:block}.product-name{font-weight:700;font-size:13px}.product-en{font-family:Arial,sans-serif;direction:ltr;text-align:right;font-size:10px;color:var(--muted)}.discount{display:inline-block;color:#92d5ac;background:#1d3a2b;padding:1px 7px;border-radius:6px}.warning{color:#e2c887}.warning-row{box-shadow:inset -3px 0 #d1b46e}.empty{text-align:center;padding:30px 16px;color:var(--muted);font-size:12px}footer{padding:10px 15px;color:var(--muted);font-size:11px;border-top:1px solid var(--line)}#groups{overflow:auto;flex:1;padding:0 14px}.group{border:1px solid var(--line);border-radius:9px;margin-bottom:12px;padding:12px}.group h3{font-size:15px}.group li{display:flex;justify-content:space-between;gap:10px;padding:6px 0;font-size:12px;border-bottom:1px solid #2a343f}.group ul{list-style:none;padding:0;margin:8px 0}.group small{display:block}.cart-footer{border-top:1px solid var(--line);padding:16px;display:flex;flex-direction:column;gap:10px}.cart-footer strong{font-size:22px}.cart-footer small{font-size:10px}.row-action{padding:5px 9px;font-size:11px}.notice{border:1px solid #596276;border-radius:9px;padding:12px;margin-bottom:14px;color:#cad5e3}dialog{color:var(--text);background:var(--panel);border:1px solid #4a5a6d;border-radius:16px;padding:0;width:min(700px,calc(100vw - 36px));max-height:calc(100dvh - 40px)}dialog::backdrop{background:#000a}.dialog-head{display:flex;justify-content:space-between;align-items:center;padding:16px 20px;border-bottom:1px solid var(--line)}.close{font-size:24px;width:44px;padding:0;background:transparent}.dialog-body{padding:18px 20px;max-height:65dvh;overflow:auto}.dialog-body>p{color:var(--muted);font-size:12px;margin-bottom:15px}.dialog-actions{display:flex;gap:10px;padding:15px 20px;border-top:1px solid var(--line)}.check{display:flex;align-items:center;gap:10px;min-height:46px}.credential{display:flex;flex-direction:column;gap:6px;margin-top:20px}.check span{font-size:11px;color:var(--muted)}#sellers{max-height:200px;overflow:auto;border:1px solid var(--line);padding:8px 12px;border-radius:9px;margin:10px 0}#sellerSearch{margin-top:10px;width:100%}.offer{padding:12px;border:1px solid var(--line);border-radius:9px;margin:10px 0}.offer button{margin-top:10px}.offer p{font-size:12px}.dialog-body h3{margin:12px 0}.money{white-space:nowrap}\n@media(max-width:1100px){.app{grid-template-columns:120px minmax(0,1fr)}.nav{padding:20px 8px}.brand{font-size:22px}main{padding:16px}.workspace{grid-template-columns:minmax(0,1fr) 235px}.controls{gap:10px}.controls button{padding:9px 12px}.panel-head{flex-wrap:wrap}.panel-head input{width:100%}.controls #days{width:110px}}\n@media(max-width:800px){.app{display:block;height:auto;overflow:visible}.nav{display:flex;flex-direction:row;align-items:center;flex-wrap:wrap;padding:10px;border-bottom:1px solid var(--line);gap:4px}.nav p,.nav-note,.nav>a:last-of-type{display:none}.brand{margin-left:auto}.nav>a:not(.brand),.nav>button{padding:9px;font-size:12px}main{overflow:visible}.workspace{display:flex;flex-direction:column}.controls{align-items:center}.controls label{flex:1}.controls #days{width:100%}.controls fieldset{flex:1}.controls #load{margin-right:0}.controls>button{flex:1}.table-wrap{max-height:55dvh}table{min-width:650px}.cart{max-height:500px}.source{font-size:10px}h1{font-size:24px}.controls legend{font-size:12px}.segment button{font-size:12px;padding:10px}header{gap:8px}.dialog-body{max-height:60dvh}}\n/* Keep Arabic action labels and stock headings intact on compact tablets. */\nth{white-space:nowrap}.row-action{white-space:nowrap}th:last-child{width:82px}td small{font-size:10px}.product-name{font-size:14px}\n@media(max-width:800px){\n .controls{display:grid;grid-template-columns:1fr 1fr;align-items:end}.controls>button{width:100%;min-width:0}.controls #days{width:100%}.segment{width:100%}.segment button{flex:1;white-space:nowrap;padding:10px 8px}\n .table-wrap{overflow-y:auto;overflow-x:hidden;max-height:65dvh}table,tbody{display:block;width:100%;min-width:0}thead{display:none}tbody tr{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:15px 12px;border-bottom:1px solid var(--line)}tbody td{display:block;border:0;padding:0;min-width:0}tbody td:first-child{grid-column:1;width:auto;min-height:44px;display:flex;align-items:center}tbody td:nth-child(2){grid-column:2/4}tbody td:nth-child(3):before,tbody td:nth-child(4):before,tbody td:nth-child(5):before{display:block;color:var(--muted);font-size:11px}tbody td:nth-child(3):before{content:'الرصيد'}tbody td:nth-child(4):before{content:'المستهدف'}tbody td:nth-child(5):before{content:'المطلوب'}tbody td:nth-child(6){grid-column:1/3}tbody td:last-child{grid-column:3}tbody td[colspan]{grid-column:1/-1}input.qty{width:100%}.row-action{width:100%}\n}\n","type":"text/css"},"/purchases.js":{"body":"import { readDays, buildNeeds, distribute, filterOffers, offerKey, groupCart, numberOrNull } from './purchases-core.js';\nconst $ = id => document.getElementById(id);\nconst esc = value => String(value ?? '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst fmt = n => Number.isFinite(n) ? new Intl.NumberFormat('ar-EG',{maximumFractionDigits:2}).format(n) : '—';\nconst PREF='novaPurchasePrefsV1', DRAFT='novaPurchaseDraftV1';\nlet prefs={days:21,level:'ideal',suppliers:['aumet','pharmaoverseas'],aumetSellers:[]};\ntry{const p=JSON.parse(localStorage.getItem(PREF)||'null');if(p&&typeof p==='object')prefs={...prefs,...p};}catch{}\nprefs.suppliers=Array.isArray(prefs.suppliers)?prefs.suppliers.filter(x=>['aumet','pharmaoverseas'].includes(x)):[];\nprefs.aumetSellers=Array.isArray(prefs.aumetSellers)?prefs.aumetSellers.map(String):[];\nlet rawItems=[],items=[],sellers=[],offersByItem=new Map(),dashboardPin='',busy=false,generation=0,lastText='',pendingSellerIds=new Set();\nlet cartPlans=[],sentLines=new Set(),pendingStockLoad=false;\nconst provider=()=>window.NOVA_SUPPLIER_PROVIDER;\nfunction status(text,error=false){$('status').textContent=text;$('status').classList.toggle('warning',error);}\nfunction persist(){try{localStorage.setItem(PREF,JSON.stringify(prefs));}catch{status('تعذر حفظ الاختيارات على الجهاز',true);}}\nfunction invalidate(){cartPlans=[];generation++;items.forEach(i=>{i.allocations=[];i.unallocated=i.qty;});render();}\nfunction setBusy(value){busy=value;['load','distribute','days','minimum','ideal','openSettings'].forEach(id=>$(id).disabled=value);}\nfunction levelView(){['minimum','ideal'].forEach(id=>$(id).setAttribute('aria-pressed',String(id===prefs.level)));}\nfunction rebuild(){try{prefs.days=readDays($('days').value);items=buildNeeds(rawItems,prefs);offersByItem.clear();generation++;persist();render();}catch(e){status(e.message,true);}}\nfunction visibleItems(){const q=$('search').value.trim().toLocaleLowerCase();return items.filter(i=>!q||`${i.name} ${i.nameEn||''} ${i.code||''}`.toLocaleLowerCase().includes(q));}\nfunction render(){\n const view=visibleItems();$('count').textContent=`(${items.length})`;\n $('rows').innerHTML=view.length?view.map(i=>{\n  const allocation=i.allocations?.[0],found=allocation?.offer;\n  const warning=i.issue||(i.unallocated>0&&i.allocations?.length?'كمية متبقية بلا عرض':'');\n  return `<tr data-key=\"${esc(i.key)}\" class=\"${warning?'warning-row':''}\"><td><input type=\"checkbox\" data-action=\"select\" aria-label=\"تحديد ${esc(i.name)}\" ${i.selected?'checked':''} ${i.issue||busy?'disabled':''}></td><td><div class=\"product-name\">${esc(i.name)}</div><div class=\"product-en\">${esc(i.nameEn||'')}</div><small title=\"${esc(i.basis||i.issue||'')}\">${esc(i.code||'')}</small></td><td>${fmt(numberOrNull(i.stock))}</td><td>${fmt(i.target)}</td><td><input class=\"qty\" type=\"text\" inputmode=\"numeric\" data-action=\"qty\" aria-label=\"الكمية المطلوبة ${esc(i.name)}\" value=\"${esc(i.qty)}\" ${i.issue||busy?'disabled':''}></td><td>${found?`<b>${esc(found.sellerName||supplierName(found.supplierId))}</b><small class=\"money\">${fmt(allocation.price)} ج.م <span class=\"discount\">${fmt(allocation.discount)}٪</span></small>${i.allocations.length>1?`<small>مقسم على ${fmt(i.allocations.length)} عروض</small>`:''}${allocation.quantityUnconfirmed?'<small class=\"warning\">كمية المورد غير محددة</small>':''}`:`<small>${esc(i.issue||'اختَر عرضًا أو وزّع تلقائيًا')}</small>`}${warning?`<small class=\"warning\">${esc(warning)}</small>`:''}</td><td><button class=\"row-action\" data-action=\"offers\" ${busy?'disabled':''}>العروض</button></td></tr>`;\n }).join(''):'<tr><td colspan=\"7\" class=\"empty\">'+(rawItems.length?'لا توجد نواقص مطابقة للاختيار الحالي.':'حدّث النواقص لقراءة مخزون الصيدلية.')+'</td></tr>';\n $('selectAll').disabled=busy;\n $('selectAll').checked=view.length>0&&view.every(i=>i.selected||i.issue);\n const groups=groupCart(items);$('groupCount').textContent=`${fmt(groups.length)} مجموعات`;\n $('groups').innerHTML=groups.length?groups.map(groupHtml).join(''):'<p class=\"empty\">لم يتم توزيع أصناف بعد.</p>';\n $('total').textContent=groups.length?fmt(groups.reduce((sum,g)=>sum+g.total,0))+' ج.م':'— ج.م';\n $('review').disabled=!groups.length||busy;\n}\nfunction supplierName(id){return id==='aumet'?'أوميت':id==='pharmaoverseas'?'فارما أوفرسيز':id;}\nfunction groupHtml(g){return `<section class=\"group\"><h3>${esc(supplierName(g.supplierId))}</h3>${g.sellerName?`<small>${esc(g.sellerName)}</small>`:''}<ul>${g.lines.map(l=>`<li><span>${esc(l.name)}</span><b>${fmt(l.qty)} علبة</b></li>`).join('')}</ul><b>${fmt(g.total)} ج.م</b><small>قائمة تجهيز محلية · قبل الشحن وأي عروض غير مؤكدة</small></section>`;}\nfunction configValid(){if(!prefs.suppliers.length){status('اختَر موردًا واحدًا على الأقل من الإعدادات',true);return false;}if(prefs.suppliers.includes('aumet')&&!prefs.aumetSellers.length){status('حدّد مخازن أوميت المسموح بها أولًا',true);openSettings(false);return false;}return true;}\nasync function loadStock(){\n if(busy)return;\n if(!dashboardPin){pendingStockLoad=true;openSettings(false);$('dashboardPin').focus();$('sourceState').textContent='STOCK LIVE · محتاج رقم الداشبورد';status('اكتب رقم دخول الداشبورد في الخانة المفتوحة ثم احفظ؛ هيبدأ تحميل النواقص تلقائيًا.',true);return;}\n pendingStockLoad=false;\n try{prefs.days=readDays($('days').value);}catch(e){status(e.message,true);return;}\n setBusy(true);status('جارٍ قراءة النواقص من STOCK LIVE…');\n try{\n  const result=await provider().purchasingStock(dashboardPin);\n  if(!result.ok||!Array.isArray(result.items))throw new Error(result.error==='source-auth-required'?'اكتب رقم دخول الداشبورد في إعدادات الموردين لقراءة المخزون':result.error==='source-not-ready'?'مصدر المشتريات يحتاج تحديث السيرفر؛ لم يتم تحميل بيانات قديمة بدلًا منه':'تعذر قراءة مخزون الصيدلية');\n  rawItems=result.items;rebuild();$('sourceState').textContent='STOCK LIVE · متصل';$('sourceState').parentElement.classList.add('ready');\n  const date=new Date(result.sourceUpdatedAt||result.generatedAt);$('sourceTime').textContent=Number.isNaN(date.getTime())?'وقت تحديث المصدر غير متاح':'آخر تحديث المصدر '+date.toLocaleString('ar-EG',{timeZone:'Africa/Cairo'});\n  status(`تمت قراءة ${fmt(rawItems.length)} صنف؛ ${fmt(items.length)} بحاجة للطلب. راجع الكميات قبل التوزيع.`);\n }catch(e){if(e.message==='source-auth-required'){dashboardPin='';pendingStockLoad=true;openSettings(false);$('dashboardPin').focus();}const message=e.message==='pin-required'?'اكتب رقم موردين نوفا عند طلبه للاتصال':e.message==='source-auth-required'?'اكتب رقم دخول الداشبورد في إعدادات الموردين':e.message==='source-not-ready'?'مصدر المشتريات يحتاج تحديث السيرفر':e.message==='source-unavailable'?'تعذر الاتصال بمصدر المخزون؛ أعد المحاولة':e.message;status(message||'تعذر الاتصال بالمصدر',true);$('sourceState').textContent=e.message==='source-auth-required'?'STOCK LIVE · راجع رقم الداشبورد':e.message==='pin-required'?'STOCK LIVE · محتاج رقم موردين نوفا':'STOCK LIVE · تعذر التحديث';$('sourceState').parentElement.classList.remove('ready');}\n finally{setBusy(false);render();}\n}\nasync function searchOffers(item){\n const r=await provider().search(item.nameEn||item.name,{requestedQty:item.qty,supplierIds:prefs.suppliers});\n const rows=(r.results||[]).flatMap(x=>x.offers||[]);offersByItem.set(item.key,rows);return rows;\n}\nasync function allocateAll(){\n if(busy||!configValid())return;if(!items.some(i=>i.selected)){status('حدّد الأصناف المطلوبة أولًا',true);return;}\n const token=++generation;setBusy(true);items.forEach(i=>{i.allocations=[];i.unallocated=i.qty;});render();\n let done=0,fail=0;const selected=items.filter(i=>i.selected&&!i.issue);\n try{for(const item of selected){\n  status(`جارٍ مقارنة عروض الصنف ${fmt(++done)} من ${fmt(selected.length)}…`);\n  try{const rows=await searchOffers(item);if(token!==generation)return;Object.assign(item,distribute(item,rows,prefs));}catch{fail++;item.allocations=[];item.unallocated=item.qty;}\n  render();\n  // Stay below the suppliers' 20 requests/minute per account, even for cached fast responses.\n  if(done<selected.length)await new Promise(resolve=>setTimeout(resolve,3100));\n }\n const remain=selected.filter(i=>i.unallocated>0).length;\n status(`تم توزيع ${fmt(selected.length-remain)} صنف. ${fmt(remain)} يحتاج اختيارًا أو مراجعة${fail?`؛ تعذر البحث عن ${fmt(fail)} صنف`:''}. القائمة لم تُرسل إلى الموردين.`,remain>0);\n }finally{setBusy(false);render();}\n}\nasync function openOffers(item){\n if(busy)return;setBusy(true);$('offerTitle').textContent=item.name;$('offerRows').textContent='جارٍ البحث…';$('offers').showModal();\n try{const rows=await searchOffers(item);const mapped=filterOffers(item,rows,prefs);$('offerRows').innerHTML=mapped.length?mapped.map((r,index)=>`<section class=\"offer\"><b>${esc(r.offer.productName)}</b><p>${esc(supplierName(r.offer.supplierId))} · ${esc(r.offer.sellerName||'')}</p><p>${fmt(r.price)} ج.م · خصم ${fmt(r.discount)}٪ · ${r.offer.availableQuantity==null?'كمية التوفر غير محددة':`المتاح ${fmt(r.offer.availableQuantity)}`}</p>${r.reason?`<small class=\"warning\">${esc(r.reason)}</small>`:''}<button data-offer=\"${index}\" ${r.eligible?'':'disabled'}>اختيار هذا العرض</button></section>`).join(''):'لا توجد عروض مطابقة حاليًا.';\n $('offerRows').querySelectorAll('[data-offer]').forEach(button=>button.onclick=()=>{const row=mapped[Number(button.dataset.offer)],offer=row.offer;const available=numberOrNull(offer.availableQuantity);const qty=Math.min(item.qty,available===null?item.qty:Math.floor(available));if(qty<=0||qty<(numberOrNull(offer.minimumOrderQuantity)||1)){status('الكمية أقل من الحد الأدنى لطلب المورد',true);return;}item.allocations=[{...row,key:offerKey(offer),qty,quantityUnconfirmed:available===null,cartState:'local-draft'}];item.unallocated=item.qty-qty;item.selected=true;$('offers').close();render();});\n }catch{$('offerRows').textContent='تعذر قراءة عروض الموردين؛ لم تتغير الكميات.';}finally{setBusy(false);}\n}\nfunction renderSellers(){const q=$('sellerSearch').value.trim().toLocaleLowerCase();$('sellers').innerHTML=sellers.length?sellers.filter(s=>s.name.toLocaleLowerCase().includes(q)).map(s=>`<label class=\"check\"><input type=\"checkbox\" data-seller=\"${esc(s.id)}\" ${pendingSellerIds.has(String(s.id))?'checked':''} ${s.locked?'disabled':''}>${esc(s.name)}${s.locked?'<small>غير متاح لحسابك</small>':''}</label>`).join(''):'لم تُقرأ مخازن حسابك بعد. جدّد جلسة أوميت ثم اضغط تحديث.';}\nasync function refreshSellers(){\n $('refreshSellers').disabled=true;\n try{const r=await provider().listSellers();sellers=(r.sellers||[]).map(s=>({...s,id:String(s.id)}));renderSellers();if(!sellers.length)status('قائمة المخازن غير متاحة في جلسة أوميت الحالية؛ جدّد الجلسة ثم أعد القراءة',true);}\n catch{status('تعذر قراءة مخازن أوميت؛ الاختيارات المحفوظة لم تتغير',true);}finally{$('refreshSellers').disabled=false;}\n}\nfunction openSettings(checkConnection=true){pendingSellerIds=new Set(prefs.aumetSellers);['aumet','pharmaoverseas'].forEach(id=>$('supplier-'+id).checked=prefs.suppliers.includes(id));$('dashboardPin').value=dashboardPin;renderSellers();$('settings').showModal();if(checkConnection)provider().listSuppliers().then(list=>{for(const s of list){const el=$(s.id==='aumet'?'aumetState':'pharmaState');el.textContent=s.state==='ok'?'متصل':'الجلسة تحتاج تجديد';}}).catch(()=>status('تعذر فحص اتصال الموردين',true));}\n$('days').value=prefs.days;levelView();\n$('days').addEventListener('change',rebuild);\n['minimum','ideal'].forEach(level=>$(level).onclick=()=>{prefs.level=level;levelView();rebuild();});\n$('load').onclick=loadStock;$('distribute').onclick=allocateAll;$('search').oninput=render;\n$('openSettings').onclick=()=>openSettings();$('refreshSellers').onclick=refreshSellers;$('sellerSearch').oninput=renderSellers;\n$('sellers').addEventListener('change',e=>{const id=e.target.dataset.seller;if(!id)return;if(e.target.checked)pendingSellerIds.add(id);else pendingSellerIds.delete(id);});\n$('saveSettings').onclick=()=>{prefs.aumetSellers=[...pendingSellerIds];prefs.suppliers=['aumet','pharmaoverseas'].filter(id=>$('supplier-'+id).checked);dashboardPin=$('dashboardPin').value.trim();$('dashboardPin').value='';persist();invalidate();$('settings').close();status('تم حفظ الموردين والمخازن؛ حدّث النواقص أو أعد التوزيع.');if(pendingStockLoad)loadStock();};\n$('selectAll').onchange=()=>{visibleItems().forEach(i=>{if(!i.issue)i.selected=$('selectAll').checked;});render();};\n$('rows').addEventListener('change',event=>{const row=event.target.closest('[data-key]');if(!row)return;const item=items.find(i=>i.key===row.dataset.key);if(event.target.dataset.action==='select'){item.selected=event.target.checked;render();}if(event.target.dataset.action==='qty'){try{item.qty=readDays(event.target.value);item.allocations=[];item.unallocated=item.qty;render();}catch{status('اكتب كمية صحيحة أكبر من صفر',true);event.target.value=item.qty;}}});\n$('rows').addEventListener('click',event=>{const button=event.target.closest('[data-action=offers]');if(button)openOffers(items.find(i=>i.key===button.closest('[data-key]').dataset.key));});\n$('closeOffers').onclick=()=>$('offers').close();$('closeReview').onclick=()=>$('reviewDialog').close();\n$('review').onclick=()=>{const groups=groupCart(items);$('reviewGroups').innerHTML=groups.map(groupHtml).join('');lastText=groups.map(g=>`${supplierName(g.supplierId)}${g.sellerName?' — '+g.sellerName:''}\\n${g.lines.map(l=>`${l.name} × ${l.qty} — ${l.price} ج.م`).join('\\n')}\\nالإجمالي ${g.total} ج.م`).join('\\n\\n');$('savedState').textContent='';cartPlans=[];$('cartPlans').textContent='';$('cartStatus').textContent='';$('applyAumet').hidden=true;$('prepareAumet').disabled=!groups.some(g=>g.supplierId==='aumet');$('reviewDialog').showModal();};\n$('saveDraft').onclick=()=>{try{const groups=groupCart(items);localStorage.setItem(DRAFT,JSON.stringify({version:1,id:crypto.randomUUID(),savedAt:new Date().toISOString(),state:'local-draft',days:prefs.days,level:prefs.level,groups}));$('savedState').textContent='اتحفظت قائمة التجهيز في نوفا على الجهاز. لم تُضف إلى سلة المورد.';}catch{$('savedState').textContent='تعذر حفظ القائمة على الجهاز؛ انسخها قبل إغلاق الصفحة.';}};\n$('copyDraft').onclick=async()=>{try{await navigator.clipboard.writeText(lastText);$('savedState').textContent='تم نسخ القائمة.';}catch{$('savedState').textContent='النسخ غير متاح في المتصفح الحالي.';}};\nrender();\n\nconst lineIdentity=l=>[l.offer.supplierProductId,l.offer.sellerId,l.qty].join('::');\nconst cartMessage=code=>({'cart-session-required':'جلسة أوميت تحتاج تجديدًا يدعم السلة','cart-payment-conflict':'هناك طريقة دفع مختلفة في السلة؛ راجعها داخل أوميت أولًا','cart-payment-unverified':'طريقة الدفع لهذا العرض غير مؤكدة؛ أضفه من أوميت مباشرة','cart-offer-changed':'عرض المورد أو السعر اتغير؛ أعد مقارنة العروض','cart-stock-changed':'الكمية المتاحة اتغيرت؛ راجع الكمية','cart-conflict':'السلة اتغيرت أثناء المراجعة؛ اقرأها من جديد','cart-plan-expired':'انتهت مدة المراجعة؛ اقرأ السلة من جديد','cart-session-changed':'الجلسة اتجددت؛ اقرأ السلة من جديد','cart-readback-unavailable':'لم نتمكن من تأكيد النتيجة؛ راجع سلة أوميت قبل أي محاولة جديدة','cart-upstream-error':'تعذرت الإضافة؛ راجع سلة أوميت قبل المحاولة'})[code]||'تعذر تأكيد سلة أوميت؛ راجعها في حسابك';\nfunction cartBusy(value){setBusy(value);['prepareAumet','applyAumet','closeReview'].forEach(id=>$(id).disabled=value);$('reviewDialog').onkeydown=e=>{if(value&&e.key==='Escape')e.preventDefault();};}\n$('prepareAumet').onclick=async()=>{\n if(busy)return;cartPlans=[];$('applyAumet').hidden=true;$('cartPlans').textContent='';\n const lines=groupCart(items).filter(g=>g.supplierId==='aumet').flatMap(g=>g.lines).filter(l=>!sentLines.has(lineIdentity(l)));\n if(!lines.length){$('cartStatus').textContent='لا توجد أصناف أوميت جديدة للإضافة في هذه القائمة.';return;}\n cartBusy(true);\n try{for(const line of lines){$('cartStatus').textContent=`قراءة سلة أوميت ومراجعة ${line.name}…`;const item=items.find(i=>i.key===line.itemKey);const plan=await provider().previewAumetCart({productId:String(line.offer.supplierProductId),sellerId:String(line.offer.sellerId),quantity:line.qty,price:line.price,query:item.nameEn||item.name});cartPlans.push({...plan,line});if(lines.length>1)await new Promise(r=>setTimeout(r,3100));}\n $('cartPlans').innerHTML=cartPlans.map(p=>`<p>${esc(p.line.name)}: في السلة ${fmt(p.before)} + المطلوب ${fmt(p.quantity)} = ${fmt(p.target)}</p>`).join('');$('cartStatus').textContent='راجع الكميات ثم أكد الإضافة. لن يتم إرسال طلب شراء. فارما أوفرسيز يظل قائمة تجهيز محلية.';$('applyAumet').hidden=false;\n }catch(e){cartPlans=[];$('cartStatus').textContent=cartMessage(e.message);}finally{cartBusy(false);}\n};\n$('applyAumet').onclick=async()=>{\n if(busy||!cartPlans.length)return;cartBusy(true);let verified=0;\n try{for(const p of cartPlans){if(sentLines.has(lineIdentity(p.line)))continue;$('cartStatus').textContent=`جارٍ إضافة ومراجعة ${p.line.name}…`;const r=await provider().applyAumetCart({plan:p.plan,signature:p.signature});if(!r.ok||r.state!=='verified')throw new Error(r.error);sentLines.add(lineIdentity(p.line));verified++;}\n $('cartStatus').textContent=`تم التحقق من إضافة ${fmt(verified)} صنف إلى سلة حسابك في أوميت. لم يتم تأكيد أي طلب شراء.`;cartPlans=[];$('applyAumet').hidden=true;\n }catch(e){$('cartStatus').textContent=`تم التحقق من ${fmt(verified)} صنف. ${cartMessage(e.message)}`;/* Keep signed plans for read-back retry; never calculate a new additive target. */}\n finally{cartBusy(false);}\n};\n","type":"application/javascript"},"/purchases-core.js":{"body":"import { normalizeDigits, matchOffersToItem } from './worker/procurement/normalize.js';\n\nexport function readDays(value) {\n  const text = normalizeDigits(String(value ?? '')).trim();\n  if (!/^\\d+$/.test(text) || Number(text) < 1 || Number(text) > 3650) throw new Error('اكتب مدة صحيحة من ١ إلى ٣٦٥٠ يوم');\n  return Number(text);\n}\nexport function numberOrNull(value) {\n  if (value === null || value === undefined || String(value).trim() === '') return null;\n  const n = Number(normalizeDigits(String(value)).replace(/,/g, ''));\n  return Number.isFinite(n) ? n : null;\n}\nexport function buildNeeds(items, { days, level = 'ideal' }) {\n  days = readDays(days);\n  if (!['minimum', 'ideal'].includes(level)) throw new Error('مستوى مخزون غير صحيح');\n  const seen = new Set();\n  return (items || []).flatMap(item => {\n    const id = String(item.id || item.code || '').trim();\n    const key = `${id}::${item.unit || 'pack'}`;\n    if (!id || seen.has(key)) return [];\n    seen.add(key);\n    const stock = numberOrNull(item.stock);\n    const minimum = numberOrNull(item.minStock), ideal = numberOrNull(item.idealStock);\n    const savedTarget = level === 'minimum' ? minimum : ideal;\n    const daily = numberOrNull(item.dailySales);\n    const observation = numberOrNull(item.observedDays);\n    const coverage = daily !== null && daily >= 0 && observation > 0 ? Math.ceil(daily * days - 1e-9) : null;\n    const target = savedTarget === null && coverage === null ? null : Math.max(savedTarget ?? 0, coverage ?? 0);\n    if (stock === null || target === null) return [{ ...item, key, qty: 0, target, selected: false, issue: stock === null ? 'الرصيد غير معلوم' : 'مستوى المخزون ومعدل البيع غير متاحين' }];\n    const qty = Math.max(0, Math.ceil(target - stock - 1e-9));\n    if (qty === 0) return [];\n    // Minimum mode means only items currently below their saved minimum (or zero).\n    if (level === 'minimum' && !(stock <= 0 || (minimum !== null && stock < minimum))) return [];\n    return [{ ...item, key, target, qty, selected: true, coverage, basis: coverage === null ? 'مستوى المخزون المسجل؛ بيانات التغطية غير متاحة' : `الأكبر من المستوى المسجل وتغطية ${days} يوم`, allocations: [], unallocated: qty }];\n  });\n}\nexport function offerKey(o) { return [o.supplierId, o.sellerId ?? '', o.supplierProductId].map(String).join('::'); }\nexport function offerPrice(o) {\n  // best_price and discountPct in Aumet are not yet verified; never treat them as final cost.\n  const price = numberOrNull(o.netEffectivePrice ?? o.unitPrice);\n  const publicPrice = numberOrNull(o.publicPrice);\n  return { price, discount: price !== null && publicPrice > 0 && price >= 0 && price <= publicPrice ? Math.round((1 - price / publicPrice) * 10000) / 100 : null };\n}\nexport function filterOffers(item, rows, settings, now = Date.now()) {\n  const known = new Set(matchOffersToItem({ name: item.nameEn || item.name }, rows.map(r => r.offer || r)).filter(r => r.score === 1 && !r.needsReview).map(r => offerKey(r.offer)));\n  return rows.map(row => {\n    const offer = row.offer || row;\n    const pricing = offerPrice(offer);\n    const exactBarcode = item.gtin && offer.barcode && String(item.gtin) === String(offer.barcode);\n    const selectedSupplier = settings.suppliers.includes(offer.supplierId);\n    const selectedSeller = offer.supplierId !== 'aumet' || (offer.sellerId != null && settings.aumetSellers.includes(String(offer.sellerId)));\n    const stamp = Date.parse(offer.lastUpdated || '');\n    const fresh = Number.isFinite(stamp) && now - stamp <= 6 * 3600000 && stamp <= now + 60000;\n    const match = exactBarcode || known.has(offerKey(offer));\n    const eligible = selectedSupplier && selectedSeller && match && fresh && offer.currency === 'EGP' && pricing.price !== null && pricing.price >= 0 && pricing.discount !== null && ['in_stock', 'low'].includes(offer.stockStatus) && (numberOrNull(offer.availableQuantity) === null || offer.availableQuantity > 0);\n    return { offer, ...pricing, eligible, reason: !selectedSupplier ? 'المورد مستبعد' : !selectedSeller ? 'المخزن غير محدد' : !match ? 'راجع مطابقة الصنف والعبوة' : !fresh ? 'العرض قديم أو بلا تاريخ' : pricing.discount === null ? 'الخصم غير مؤكد' : !['in_stock', 'low'].includes(offer.stockStatus) ? 'التوفر غير مؤكد' : '' };\n  });\n}\nexport function distribute(item, rows, settings, now = Date.now()) {\n  let remaining = item.qty;\n  const allocations = [], seen = new Set();\n  const ranked = filterOffers(item, rows, settings, now).filter(r => r.eligible).sort((a,b) => b.discount - a.discount || a.price - b.price || offerKey(a.offer).localeCompare(offerKey(b.offer)));\n  for (const row of ranked) {\n    const key = offerKey(row.offer);\n    if (seen.has(key)) continue;\n    seen.add(key);\n    const available = numberOrNull(row.offer.availableQuantity);\n    const qty = Math.min(remaining, available === null ? remaining : Math.floor(available));\n    const moq = numberOrNull(row.offer.minimumOrderQuantity) ?? 1;\n    if (qty < moq || qty < 1) continue;\n    allocations.push({ ...row, key, qty, quantityUnconfirmed: available === null, cartState: 'local-draft' });\n    remaining -= qty;\n    if (remaining === 0) break;\n  }\n  return { allocations, unallocated: remaining };\n}\nexport function groupCart(items) {\n  const groups = new Map();\n  for (const item of items.filter(i => i.selected)) for (const a of item.allocations || []) {\n    const id = `${a.offer.supplierId}::${a.offer.sellerId ?? ''}`;\n    if (!groups.has(id)) groups.set(id, { id, supplierId: a.offer.supplierId, sellerId: a.offer.sellerId, sellerName: a.offer.sellerName, lines: [], total: 0 });\n    const group = groups.get(id);\n    group.lines.push({ name: item.name, itemKey: item.key, ...a });\n    group.total += a.price * a.qty;\n  }\n  return [...groups.values()].map(g => ({ ...g, total: Math.round(g.total * 100) / 100 }));\n}\n","type":"application/javascript"},"/supplier-provider.js":{"body":"/* Default supplier provider for the app: talks to the NOVA Worker (same origin).\n   Only defined when no other provider exists (tests inject their own).\n   The PIN is asked once and kept in this browser only. No supplier passwords here:\n   supplier logins are done by a separate secure job and never reach the app. */\n(function () {\n  'use strict';\n  if (window.NOVA_SUPPLIER_PROVIDER) return;\n\n  var KEY = 'novaApiPin';\n\n  function getPin(forceAsk) {\n    var pin = null;\n    try { pin = localStorage.getItem(KEY); } catch (e) { pin = null; }\n    if (!pin || forceAsk) {\n      pin = window.prompt('رقم PIN الموردين');\n      if (pin) { try { localStorage.setItem(KEY, pin); } catch (e) { /* ignore */ } }\n    }\n    return pin;\n  }\n\n  function call(path, options, retried) {\n    var pin = getPin(false);\n    if (!pin) return Promise.reject(new Error('pin-required'));\n    var init = Object.assign({ headers: {} }, options || {});\n    init.headers = Object.assign({ 'X-Nova-Pin': pin, 'Content-Type': 'application/json' }, init.headers);\n    return fetch(path, init).then(function (res) {\n      if (res.status === 401 && !retried) {\n        try { localStorage.removeItem(KEY); } catch (e) { /* ignore */ }\n        return call(path, options, true);\n      }\n      return res.json().catch(function () { return {}; }).then(function (data) {\n        if (!res.ok) throw new Error(data.error || ('http-' + res.status));\n        return data;\n      });\n    });\n  }\n\n  function mapState(s) {\n    if (s === 'ok') return 'ok';\n    if (s === 'expired') return 'error';\n    return 'off';\n  }\n\n  window.NOVA_SUPPLIER_PROVIDER = {\n    previewAumetCart: function (line) { return call('/api/purchases/aumet-cart/preview', {method:'POST',body:JSON.stringify(line)}); },\n    applyAumetCart: function (plan) { return call('/api/purchases/aumet-cart/apply', {method:'POST',body:JSON.stringify(plan)}); },\n    listSellers: function () { return call('/api/suppliers/sellers', { method: 'GET' }); },\n    purchasingStock: function (dashboardPin) { return call('/api/purchases/stock', { method: 'POST', body: JSON.stringify({ dashboardPin: dashboardPin || '' }) }); },\n    search: function (query, opts) {\n      return call('/api/suppliers/search', {\n        method: 'POST',\n        body: JSON.stringify({ query: query, requestedQty: (opts && opts.requestedQty) || 1, supplierIds: opts && opts.supplierIds }),\n      });\n    },\n    listSuppliers: function () {\n      return call('/api/suppliers/status', { method: 'GET' }).then(function (r) {\n        return (r.suppliers || []).map(function (s) {\n          return {\n            id: s.id,\n            name: s.name,\n            state: mapState(s.state),\n            available: true,\n            message: s.state === 'expired' ? 'الجلسة انتهت' : '',\n          };\n        });\n      });\n    },\n    testSupplier: function (id) {\n      return call('/api/suppliers/status', { method: 'GET' }).then(function (r) {\n        var s = (r.suppliers || []).filter(function (x) { return x.id === id; })[0];\n        return { ok: !!s && s.state === 'ok', message: s && s.state === 'ok' ? 'الاتصال سليم' : 'الجلسة منتهية أو غير مربوطة' };\n      });\n    },\n    connectSupplier: function () {\n      return Promise.resolve({ ok: false, message: 'إضافة مورد جديد بتتم بالتواصل معانا (محتاج ربط مخصوص)' });\n    },\n  };\n})();\n\n","type":"application/javascript"},"/worker/procurement/normalize.js":{"body":"// Price normalization for procurement offers (Epic #53, task 04):\n// product-name parsing, comparable unit prices, product keys, offer matching.\n// Dependency-free ES module; runs in Cloudflare Workers and Node 22.\n\nconst AR_DIGITS = /[٠-٩۰-۹]/g;\n\nexport function normalizeDigits(text) {\n  return String(text ?? '').replace(AR_DIGITS, (ch) => {\n    const code = ch.codePointAt(0);\n    return String(code >= 0x660 && code <= 0x669 ? code - 0x660 : code - 0x6f0);\n  });\n}\n\nconst NUM = '\\\\d+(?:\\\\.\\\\d+)?';\nconst EDGE = '(?![\\\\p{L}\\\\p{N}])';\nconst WEIGHT = '(?:MCG|MG|GM|G|مجم|غرام|جم)';\nconst VOLUME = '(?:ML|مل)';\n\nconst COMBO_RE = new RegExp(\n  `(${NUM})\\\\s*(${WEIGHT})\\\\s*\\\\.?\\\\s*\\\\/\\\\s*(${NUM})?\\\\s*(${WEIGHT}|${VOLUME})${EDGE}`,\n  'iu',\n);\nconst SLASH_RE = new RegExp(`(${NUM})\\\\s*\\\\/\\\\s*(${NUM})\\\\s*(MCG|MG|GM|G)${EDGE}`, 'iu');\nconst DASH_RE = new RegExp(`(${NUM})\\\\s*-\\\\s*(${NUM})\\\\s*(MCG|MG|GM|G)${EDGE}`, 'iu');\nconst PERCENT_RE = /(\\d+(?:\\.\\d+)?)\\s*%/;\nconst SIMPLE_RE = new RegExp(`(${NUM})\\\\s*(${WEIGHT}|IU)${EDGE}`, 'iu');\n\nconst G_UNITS = new Set(['gm', 'g', 'جم', 'غرام']);\nconst MG_UNITS = new Set(['mg', 'مجم']);\n\nfunction toMg(value, unit) {\n  const u = unit.toLowerCase();\n  if (G_UNITS.has(u)) return String(Number(value) * 1000);\n  return value;\n}\n\nfunction normalizeSimpleUnit(unit) {\n  const u = unit.toLowerCase();\n  if (G_UNITS.has(u)) return 'g';\n  if (MG_UNITS.has(u)) return 'mg';\n  return u;\n}\n\nfunction comboStrength(m) {\n  const [, n1, u1, n2, u2] = m;\n  const u2Lower = u2.toLowerCase();\n  if (u2Lower === 'ml' || u2Lower === 'مل') {\n    return { value: toMg(n1, u1), unit: n2 ? `mg/${n2}ml` : 'mg/ml' };\n  }\n  return { value: `${toMg(n1, u1)}/${toMg(n2, u2)}`, unit: 'mg' };\n}\n\nfunction findStrength(s) {\n  let m = COMBO_RE.exec(s);\n  if (m) return { strength: comboStrength(m), index: m.index, length: m[0].length };\n  m = SLASH_RE.exec(s);\n  if (m) {\n    const factor = G_UNITS.has(m[3].toLowerCase()) ? 1000 : 1;\n    const a = factor === 1 ? m[1] : String(Number(m[1]) * factor);\n    const b = factor === 1 ? m[2] : String(Number(m[2]) * factor);\n    return { strength: { value: `${a}/${b}`, unit: 'mg' }, index: m.index, length: m[0].length };\n  }\n  m = DASH_RE.exec(s);\n  if (m) {\n    const factor = G_UNITS.has(m[3].toLowerCase()) ? 1000 : 1;\n    const a = factor === 1 ? m[1] : String(Number(m[1]) * factor);\n    const b = factor === 1 ? m[2] : String(Number(m[2]) * factor);\n    return { strength: { value: `${a}/${b}`, unit: 'mg' }, index: m.index, length: m[0].length };\n  }\n  m = PERCENT_RE.exec(s);\n  if (m) return { strength: { value: m[1], unit: '%' }, index: m.index, length: m[0].length };\n  m = SIMPLE_RE.exec(s);\n  if (m) {\n    return {\n      strength: { value: m[1], unit: normalizeSimpleUnit(m[2]) },\n      index: m.index,\n      length: m[0].length,\n    };\n  }\n  return null;\n}\n\nconst PACK_UNIT_RE =\n  /(QUICKETABS?|LACTABS?|TABLETS?|TABS?|CAPSULES?|CAPS?|SACHETS?|SACHE|SUPPS?|AMPS?|VIALS?|VAIL|ML|DROPS|BOTTLE|أقراص|قرص|شرائط|شريط|كبسول[ةات]|أمبول|امبول|مل)(?![\\p{L}\\p{N}])/giu;\n\nconst BARE_VIAL_RE = /(?:^|[^\\p{L}\\p{N}])(VIALS?|VAIL)(?![\\p{L}\\p{N}])/iu;\n\nfunction packUnit(text) {\n  const t = text.toLowerCase();\n  if (t.includes('tab') || t === 'قرص' || t === 'أقراص') return 'tab';\n  if (t.includes('cap') || t.startsWith('كبسول')) return 'cap';\n  if (t.includes('sache')) return 'sachet';\n  if (t.includes('supp')) return 'supp';\n  if (t.includes('amp') || t === 'أمبول' || t === 'امبول') return 'amp';\n  if (t === 'vial' || t === 'vials' || t === 'vail') return 'vial';\n  if (t === 'ml' || t === 'مل') return 'ml';\n  if (t.includes('drop')) return 'drops';\n  if (t.includes('bottle')) return 'bottle';\n  if (t === 'شريط' || t === 'شرائط') return 'strip';\n  return 'other';\n}\n\nfunction findPack(masked) {\n  PACK_UNIT_RE.lastIndex = 0;\n  let m;\n  while ((m = PACK_UNIT_RE.exec(masked)) !== null) {\n    const window = masked.slice(Math.max(0, m.index - 30), m.index);\n    const nums = window.match(/\\d+/g);\n    if (nums) return { count: Number(nums[nums.length - 1]), unit: packUnit(m[1]) };\n  }\n  if (BARE_VIAL_RE.test(masked)) return { count: 1, unit: 'vial' };\n  return null;\n}\n\nconst FORM_PATTERNS = [\n  [/SUPP/iu, 'supp'],\n  [/SACHE/iu, 'sachet'],\n  [/SUSP/iu, 'susp'],\n  [/(?:^|[^\\p{L}\\p{N}])(?:SYP|SYRUP)(?![\\p{L}\\p{N}])|شراب/iu, 'syrup'],\n  [/(?:^|[^\\p{L}\\p{N}])(?:DROPS?|DPS)(?![\\p{L}\\p{N}])|OPHTHALMIC|نقط/iu, 'drops'],\n  [/(?:^|[^\\p{L}\\p{N}])AMPS?(?![\\p{L}\\p{N}])|أمبول|امبول/iu, 'amp'],\n  [/(?:^|[^\\p{L}\\p{N}])VIALS?(?![\\p{L}\\p{N}])|(?:^|[^\\p{L}\\p{N}])VAIL(?![\\p{L}\\p{N}])/iu, 'vial'],\n  [/(?:^|[^\\p{L}\\p{N}])CAPS(?:ULES?)?(?![\\p{L}\\p{N}])|كبسول/iu, 'cap'],\n  [/TAB|قرص|أقراص|شريط/iu, 'tab'],\n  [/CREAM|كريم/iu, 'cream'],\n  [/(?:^|[^\\p{L}\\p{N}])GEL(?![\\p{L}\\p{N}])|جل/iu, 'gel'],\n  [/(?:^|[^\\p{L}\\p{N}])EFF(?![\\p{L}\\p{N}])/iu, 'eff'],\n];\n\nfunction findForm(s) {\n  for (const [re, form] of FORM_PATTERNS) {\n    if (re.test(s)) return form;\n  }\n  return 'other';\n}\n\nfunction maskRange(s, index, length) {\n  return s.slice(0, index) + ' '.repeat(length) + s.slice(index + length);\n}\n\nexport function parseProductName(name) {\n  const raw = String(name ?? '');\n  const s = normalizeDigits(raw).replace(/\\s+/g, ' ').trim();\n  const strengthMatch = findStrength(s);\n  const strength = strengthMatch ? strengthMatch.strength : null;\n  const masked = strengthMatch ? maskRange(s, strengthMatch.index, strengthMatch.length) : s;\n  const pack = findPack(masked);\n  const form = findForm(s);\n  const firstDigit = s.search(/\\d/);\n  const brand = (firstDigit === -1 ? s : s.slice(0, firstDigit))\n    .replace(/\\s+/g, ' ')\n    .trim()\n    .toUpperCase();\n  return { brand, strength, form, pack, raw };\n}\n\nexport function comparableUnitPrice(offer, parsed) {\n  const price = offer?.netEffectivePrice ?? offer?.unitPrice;\n  const count = parsed?.pack?.count;\n  if (typeof price !== 'number' || !Number.isFinite(price)) return null;\n  if (typeof count !== 'number' || !(count > 0)) return null;\n  return price / count;\n}\n\nexport function productKey(parsed) {\n  if (!parsed || !parsed.brand) return null;\n  // Many supplier names carry no strength (\"PANADOL EXTRA 24 F.C. TAB.\").\n  // Those still get a key when the pack is known; \"-\" marks the missing strength.\n  if (!parsed.strength && !parsed.pack) return null;\n  const strength = parsed.strength ? `${parsed.strength.value}${parsed.strength.unit}` : '-';\n  const packCount = parsed.pack ? String(parsed.pack.count) : '';\n  return `${parsed.brand}|${strength}|${parsed.form}|${packCount}`.toLowerCase();\n}\n\nfunction strengthId(strength) {\n  return strength ? `${strength.value}|${strength.unit}` : null;\n}\n\nconst parseCache = new Map();\nfunction parseCached(name) {\n  let hit = parseCache.get(name);\n  if (!hit) {\n    if (parseCache.size > 50000) parseCache.clear();\n    hit = parseProductName(name);\n    parseCache.set(name, hit);\n  }\n  return hit;\n}\n\nexport function matchOffersToItem(item, offers) {\n  const parsedItem = parseProductName(item?.name ?? '');\n  const itemKey = productKey(parsedItem);\n  const itemStrength = strengthId(parsedItem.strength);\n  const results = [];\n  for (const offer of offers ?? []) {\n    const parsedOffer = parseCached(offer?.productName ?? '');\n    const offerKey = productKey(parsedOffer);\n    const offerStrength = strengthId(parsedOffer.strength);\n    let score = 0;\n    const reasons = [];\n    let needsReview = false;\n    if (itemKey && offerKey && itemKey === offerKey) {\n      score = 1;\n      reasons.push('exact-product-key');\n    } else if (parsedItem.brand && parsedItem.brand === parsedOffer.brand) {\n      const formsKnown = parsedItem.form !== 'other' && parsedOffer.form !== 'other';\n      if (formsKnown && parsedItem.form !== parsedOffer.form) {\n        // Tablets vs vials (or syrup vs tablets) are never interchangeable.\n        score = 0.5;\n        reasons.push('form-differs');\n        needsReview = true;\n      } else if (itemStrength && offerStrength && itemStrength === offerStrength) {\n        score = 0.8;\n        reasons.push(\n          parsedItem.pack?.count !== parsedOffer.pack?.count ? 'pack-differs' : 'form-differs',\n        );\n      } else if (!itemStrength && !offerStrength && parsedItem.form === parsedOffer.form) {\n        // Neither name states a strength: same brand and form, only the pack differs.\n        score = 0.8;\n        reasons.push('pack-differs');\n      } else if (itemStrength && offerStrength) {\n        score = 0.5;\n        reasons.push('strength-differs');\n        needsReview = true;\n      } else {\n        score = 0.5;\n        reasons.push('brand-only');\n        needsReview = true;\n      }\n    }\n    if (score < 0.5) continue;\n    const entry = { offer, score, reasons };\n    if (needsReview) entry.needsReview = true;\n    results.push(entry);\n  }\n  results.sort((a, b) => b.score - a.score);\n  return results;\n}\n\n","type":"application/javascript"}};
